ackdrop{background:#142a35aa;backdrop-filter:blur(5px)}.discussion .close{position:absolute;right:15px;top:10px;background:none;color:#304b49;font-size:25px}.discussion h2{font-size:25px;margin:15px 0}.discussion>p{font-size:13px;color:#8c8069}textarea{display:block;width:100%;min-height:110px;font:inherit;border:1px solid #d5dacc;border-radius:7px;margin:12px 0;padding:14px}.discussion form{margin:25px 0}article{border-top:1px solid #e2e1d8;padding:20px 0}article p{white-space:pre-wrap;overflow-wrap:anywhere;line-height:1.9;font-size:14px}article time,article span{font-size:10px;color:#8b957e;margin-left:12px}article button{background:none;color:#94744c;font-size:11px;padding:5px 12px 5px 0}.answer{padding-left:20px;border-left:3px solid #ddcea8}.discussion form p{font-size:12px;color:#94744c}@media(max-width:850px){.map-layout{grid-template-columns:1fr}.map-heading{align-items:flex-start;flex-direction:column}.map-scroll{height:65vh}aside{max-height:240px}.campus{padding:24px 16px}h1{font-size:27px}.discussion{padding:25px}}
